/** pi's last measured child heights include wrapping, spacers, and explicit expansion. */
interface MeasuredContainer {
  mouseLayout?: { children: { component: object; height: number }[] };
}

export interface TranscriptTui extends MeasuredContainer {
  mode?: string;
  terminal?: { rows: number };
  getPrimaryScrollView?: () => { children?: object[]; viewportHeight?: number };
}

/** Always measure from the live end. Scrolling through history must not make it young again. */
export function offscreenHistory(root: TranscriptTui): Set<object> {
  const history = new Set<object>();
  const scroll = root.mode === "fullscreen" ? root.getPrimaryScrollView?.() : undefined;
  const document = root.mode === "fullscreen" ? scroll?.children?.[0] : root;
  const height = (root.mode === "fullscreen" ? scroll?.viewportHeight : root.terminal?.rows) ?? 0;
  if (!document || height <= 0) return history;

  function visit(container: MeasuredContainer, rowsBelow: number): void {
    const layout = container.mouseLayout?.children;
    if (!Array.isArray(layout)) return;
    for (let i = layout.length - 1; i >= 0; i--) {
      const { component, height: childHeight } = layout[i]!;
      if (rowsBelow >= height) history.add(component);
      if (rowsBelow >= height || rowsBelow + childHeight > height) visit(component, rowsBelow);
      rowsBelow += childHeight;
    }
  }
  visit(document, 0);
  return history;
}
