/**
 * Resolve the pi install this machine actually runs, so the gallery shows truth
 * rather than a pinned approximation.
 *
 * Order: explicit env, the newest nvm global install, homebrew/system globals,
 * then a repo-local install.
 */

import { existsSync, readFileSync, readdirSync, realpathSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join } from "node:path";
import { pathToFileURL } from "node:url";

export interface PiInstall {
  root: string;
  tuiRoot: string;
  version: string;
  tuiVersion: string;
  source: "env" | "nvm" | "global" | "local";
  modules: PiModules;
}

/** Dynamically loaded pi modules. Typed loosely: the harness renders, it does not build the product. */
export interface PiModules {
  coding: any;
  tui: any;
  theme: any;
  exportHtml: any;
}

const PKG = "@earendil-works/pi-coding-agent";

function packageVersion(root: string): string {
  try {
    const pkg = JSON.parse(readFileSync(join(root, "package.json"), "utf8")) as { version?: string };
    return pkg.version ?? "unknown";
  } catch {
    return "unknown";
  }
}

function nvmInstall(): string | undefined {
  const versions = join(homedir(), ".nvm", "versions", "node");
  if (!existsSync(versions)) return undefined;
  const candidates = readdirSync(versions)
    .toSorted()
    .toReversed()
    .map((entry) => join(versions, entry, "lib", "node_modules", PKG));
  return candidates.find((candidate) => existsSync(join(candidate, "dist", "index.js")));
}

function resolveRoot(): { root: string; source: PiInstall["source"] } {
  const env = process.env.PI_CODING_AGENT_ROOT;
  if (env && existsSync(join(env, "dist", "index.js"))) return { root: env, source: "env" };

  const fromNvm = nvmInstall();
  if (fromNvm) return { root: fromNvm, source: "nvm" };

  for (const prefix of ["/opt/homebrew/lib/node_modules", "/usr/local/lib/node_modules"]) {
    const candidate = join(prefix, PKG);
    if (existsSync(join(candidate, "dist", "index.js"))) return { root: candidate, source: "global" };
  }

  return { root: packageRoot(PKG, WORKSPACE), source: "local" };
}

const WORKSPACE = join(import.meta.dir, "../../packages/pi-ui");

function packageRoot(name: string, from: string): string {
  // Both pi packages expose dist/index.js as their entry point.
  return dirname(dirname(Bun.resolveSync(name, from)));
}

function resolveTuiRoot(piRoot: string): string {
  const name = "@earendil-works/pi-tui";
  try {
    return packageRoot(name, realpathSync(piRoot));
  } catch {
    return packageRoot(name, WORKSPACE);
  }
}

async function imp(path: string): Promise<any> {
  return import(pathToFileURL(path).href);
}

let cached: Promise<PiInstall> | undefined;

export async function resolvePi(): Promise<PiInstall> {
  cached ??= loadPi();
  return cached;
}

async function loadPi(): Promise<PiInstall> {
  const { root, source } = resolveRoot();
  const tuiRoot = resolveTuiRoot(root);
  const modules: PiModules = {
    coding: await imp(join(root, "dist", "index.js")),
    tui: await imp(join(tuiRoot, "dist", "index.js")),
    theme: await imp(join(root, "dist", "modes", "interactive", "theme", "theme.js")),
    exportHtml: await imp(join(root, "dist", "core", "export-html", "ansi-to-html.js")),
  };
  return {
    root,
    tuiRoot,
    version: packageVersion(root),
    tuiVersion: packageVersion(tuiRoot),
    source,
    modules,
  };
}

/** Installed extension packages (pi-code, pi-open-tui) live in the agent dir. */
export function agentPackageRoot(name: string): string | undefined {
  const candidate = join(homedir(), ".pi", "agent", "npm", "node_modules", name);
  return existsSync(candidate) ? candidate : undefined;
}
/**
 * Theme plumbing. pi's Theme class and the shipped dark/light JSON give the
 * gallery the same palette the terminal uses, including the export colors used
 * for the page chrome.
 */

import { readFileSync } from "node:fs";
import { join } from "node:path";
import type { PiInstall } from "./pi.ts";

export type ThemeName = "dark" | "light";

export interface ThemeJson {
  name?: string;
  appearance?: "dark" | "light";
  vars?: Record<string, string>;
  colors: Record<string, string>;
  export?: { pageBg?: string; cardBg?: string; infoBg?: string };
}

export interface InstalledTheme {
  name: ThemeName;
  json: ThemeJson;
  theme: any;
  pageBg: string;
  cardBg: string;
}

export function loadThemeJson(pi: PiInstall, name: ThemeName): ThemeJson {
  const path = join(pi.root, "dist", "modes", "interactive", "theme", `${name}.json`);
  return JSON.parse(readFileSync(path, "utf8")) as ThemeJson;
}

/** Resolve `vars` references (which may themselves reference vars). */
function resolveVars(json: ThemeJson): Record<string, string> {
  const vars = json.vars ?? {};
  const resolved: Record<string, string> = {};
  const resolve = (key: string, depth = 0): string => {
    if (depth > 10) return "";
    const cached = resolved[key];
    if (cached) return cached;
    const value = vars[key] ?? key;
    const next = vars[value] !== undefined ? resolve(value, depth + 1) : value;
    resolved[key] = next;
    return next;
  };
  for (const key of Object.keys(vars)) resolve(key);
  return resolved;
}

const BG_TOKEN = /Bg$|^border$|^borderAccent$|^borderMuted$/;

export function installTheme(pi: PiInstall, json: ThemeJson): InstalledTheme {
  const vars = resolveVars(json);
  const resolve = (value: string): string => vars[value] ?? value;

  const fg: Record<string, string> = {};
  const bg: Record<string, string> = {};
  for (const [key, value] of Object.entries(json.colors)) {
    const concrete = resolve(value);
    fg[key] = concrete;
    if (BG_TOKEN.test(key)) bg[key] = concrete;
  }

  pi.modules.theme.initTheme(json.name ?? "dark");
  const theme = new pi.modules.theme.Theme(fg, bg, "truecolor");
  pi.modules.theme.setThemeInstance(theme);

  return {
    name: (json.name as ThemeName) ?? "dark",
    json,
    theme,
    pageBg: json.export?.pageBg ?? "#14121a",
    cardBg: json.export?.cardBg ?? "#181620",
  };
}

/** CSS custom properties from pi's resolved tokens, for agent-side consumers. */
export function cssTokens(installed: InstalledTheme): Record<string, string> {
  try {
    return installed.theme.colors as Record<string, string>;
  } catch {
    return {};
  }
}
