import { createPiKit } from "../../packages/pi-ui/render/pi-kit.ts";
import type { RenderKit } from "../../packages/pi-ui/render/kit.ts";
import type { PiInstall } from "./pi.ts";

export function createKit(pi: PiInstall): RenderKit {
