/** A single frame of the replay: how far each stream has progressed. */
export interface PlaybackFrame {
  /** Index into SESSION_STEPS. */
  step: number;
  /** Caption for the step indicator. */
  label: string;
  /** Characters of prose, thinking or a tool title revealed so far. */
  chars: number;
  /** Output lines revealed so far. */
  lines: number;
  /** Still streaming: spinner and running status. */
  partial: boolean;
  /** Elapsed time within the current tool or thinking step. */
  elapsedMs?: number;
  /** How long this frame is on screen, in ms, at 100 tokens/second. */
  ms: number;
}

/**
 * Streaming is chunked, not batched: sizes vary the way tokens arrive, so the
 * tail visibly grows instead of jumping a line at a time. One chunk is about one
 * token, and at 100 tok/s a token frame costs 10ms.
 */
const TOKEN_MS = 10;
const OUTPUT_LINE_MS = 10;
/** Prefill is not generation: prompt context lands at thousands of tokens a second. */
const PREFILL_TOKENS_PER_SECOND = 4000;
/** A tool that takes seconds should look like it: the timer keeps moving. */
const WAIT_FRAME_MS = 80;
const CHUNK_SIZES = [3, 5, 4, 7, 2, 6, 3, 4] as const;

function chunkEnds(length: number): number[] {
  const ends: number[] = [];
  let at = 0;
  for (let i = 0; at < length; i++) {
    at = Math.min(length, at + (CHUNK_SIZES[i % CHUNK_SIZES.length] ?? 4));
    ends.push(at);
  }
  return ends;
}

function thinkingFrames(step: number, label: string, text: string): PlaybackFrame[] {
  const ends = chunkEnds(text.length);
  return [
    ...ends.map((chars, index) => ({
      step,
      elapsedMs: (index + 1) * TOKEN_MS,
      label: `${label} · thinking ${Math.round(((index + 1) / ends.length) * 100)}%`,
      chars,
      lines: 0,
      partial: true,
      ms: TOKEN_MS,
    })),
    { step, label, chars: text.length, lines: 0, partial: false, ms: TOKEN_MS },
  ];
}

function textFrames(step: number, label: string, text: string): PlaybackFrame[] {
  const ends = chunkEnds(text.length);
  return ends.map((chars, index) => ({
    step,
    label: index < ends.length - 1 ? `${label} · streaming` : label,
    chars,
    lines: 0,
    partial: index < ends.length - 1,
    ms: TOKEN_MS,
  }));
}

function toolFrames(step: number, label: string, tool: SessionTool): PlaybackFrame[] {
  const title = tool.title ?? "";
  const outputLines = (tool.output ?? "").split("\n").length;
  const frames: PlaybackFrame[] = [];
  // Arguments arrive character by character: the path or command is composed live.
  for (const chars of chunkEnds(title.length)) {
    frames.push({ step, label: `${label} · call`, chars, lines: 0, partial: true, ms: TOKEN_MS });
  }
  // A tool that ran for seconds spends those seconds on screen before output.
  if (tool.durationMs && tool.durationMs >= 1000) {
    frames.push(...waitFrames(step, label, title, tool.durationMs));
  }
  // Output arrives line by line, not in one batch.
  for (let lines = 1; lines <= outputLines; lines++) {
    frames.push({
      step,
      label: `${label} · output ${lines}/${outputLines}`,
      chars: title.length,
      lines,
      partial: true,
      elapsedMs: tool.durationMs,
      ms: OUTPUT_LINE_MS,
    });
  }
  frames.push({ step, label, chars: title.length, lines: outputLines, partial: false, ms: OUTPUT_LINE_MS });
  return frames;
}

function prefillFrames(step: number, label: string, tokens: number): PlaybackFrame[] {
  const totalMs = (tokens / PREFILL_TOKENS_PER_SECOND) * 1000;
  const parts = Math.max(1, Math.round(totalMs / WAIT_FRAME_MS));
  return Array.from({ length: parts }, (_, index) => ({
    step,
    label: `${label} · ${Math.round(((index + 1) / parts) * tokens).toLocaleString("en-US")} tok · ${PREFILL_TOKENS_PER_SECOND} tok/s`,
    chars: 0,
    lines: 0,
    partial: false,
    ms: totalMs / parts,
  }));
}

function waitFrames(step: number, label: string, title: string, durationMs: number): PlaybackFrame[] {
  const parts = Math.max(1, Math.round(durationMs / WAIT_FRAME_MS));
  return Array.from({ length: parts }, (_, index) => ({
    step,
    label: `${label} · waiting ${formatDuration((index + 1) * (durationMs / parts))}`,
    // The call is already parsed; only the result is missing while it runs.
    chars: title.length,
    lines: 0,
    partial: true,
    elapsedMs: ((index + 1) * durationMs) / parts,
    ms: durationMs / parts,
  }));
}

function framesForStep(step: SessionStep, index: number): PlaybackFrame[] {
  switch (step.kind) {
    case "prefill":
      return prefillFrames(index, step.label, step.tokens);
    case "user":
      return [{ step: index, label: step.label, chars: step.text.length, lines: 0, partial: false, ms: TOKEN_MS }];
    case "thinking":
      return thinkingFrames(index, step.label, step.text);
    case "text":
      return textFrames(index, step.label, step.text);
    case "tool":
      return toolFrames(index, step.label, step.tool);
  }
}

export const PLAYBACK: PlaybackFrame[] = SESSION_STEPS.flatMap((step, index) => framesForStep(step, index));

// Steps play sequentially. Include the simulated time spent streaming thoughts and arguments.
const stepEnds: number[] = [];
let playbackTime = 0;
for (const frame of PLAYBACK) {
  playbackTime += frame.ms;
  stepEnds[frame.step] = playbackTime;
}

export function playbackGroupDuration(indices: number[]): number | undefined {
  const first = indices[0];
  const last = indices.at(-1);
  if (first === undefined || last === undefined) return undefined;
  return stepEnds[last]! - (stepEnds[first - 1] ?? 0);
}

/** One caption per playback frame, so the scrubber reads like a trace. */
export const FRAME_LABELS: string[] = PLAYBACK.map((frame) => frame.label);

export function stepAt(frame: PlaybackFrame): SessionStep {
  const step = SESSION_STEPS[frame.step];
  if (!step) throw new Error(`playback frame ${frame.step} has no step`);
  return step;
}

/** The same slices drive both lanes, so neither invents content. */
export function partialText(text: string, chars: number): string {
  return text.slice(0, Math.max(0, chars));
}

export function partialLines(text: string, lines: number): string {
  return text.split("\n").slice(0, Math.max(0, lines)).join("\n");
}

/**
 * The argument that streams for this tool: pi shows the path or command grow as
 * the call is composed, so the replay does the same.
 */
export function streamingArgKey(name: string): string {
  if (name === "bash" || name === "powershell") return "command";
  if (name === "grep" || name === "find" || name === "ffgrep" || name === "fffind") return "pattern";
  return "path";
}

const widthsFor = (entry: EntryDef, scope: RenderScope): readonly number[] =>
  scope.widths ?? (entry.fixedWidth ? [entry.fixedWidth] : WIDTHS);

const glyphsForScope = (scope: RenderScope): readonly GlyphMode[] => scope.glyphModes ?? GLYPH_MODES;

/**
 * Render a slice of the gallery. `tailLines` moves the decay knob; the other
 * fields restrict the matrix so a live request stays small.
 */
type ThemeName = (typeof THEME_NAMES)[number];

export interface RenderScope {
  tailLines?: number;
  themes?: readonly ThemeName[];
  widths?: readonly number[];
  glyphModes?: readonly GlyphMode[];
  entries?: readonly EntryDef[];
}

export interface GalleryRender {
  payload: PagePayload;
  fixtures: Map<string, Record<string, { lines: string[] }>>;
  pi: PiInstall;
}

function cellCount(entries: readonly EntryDef[], scope: RenderScope): number {
  return entries.reduce(
    (sum, entry) =>
      sum +
      entry.states.length *
        widthsFor(entry, scope).length *
        glyphsForScope(scope).length *
        (scope.themes ?? THEME_NAMES).length,
    0,
  );
}

export async function renderGallery(scope: RenderScope = {}): Promise<GalleryRender> {
  if (scope.tailLines !== undefined) setTailLines(scope.tailLines);

  const pi = await resolvePi();
  const entries = scope.entries ?? ENTRIES;
  const themeNames = scope.themes ?? THEME_NAMES;
  const data = new Map<string, EntryData>();
  const revealData = new Map<string, Record<string, Record<CellKey, RevealStore>>>();
  const blockData = new Map<string, Record<string, Record<CellKey, BlockCell>>>();
  const fixtures = new Map<string, Record<string, { lines: string[] }>>();
  const themes: PagePayload["themes"] = {};

  for (const themeName of themeNames) {
    const installed = installTheme(pi, loadThemeJson(pi, themeName));
    const themeModule = pi.modules.theme;
    const palette = themeModule.getResolvedThemeColors(themeName) as Record<string, string>;
    const exportColors = themeModule.getThemeExportColors(themeName) as {
      pageBg?: string;
      cardBg?: string;
    };
    themes[themeName] = {
      pageBg: exportColors.pageBg ?? palette.toolPendingBg ?? "#121016",
      cardBg: exportColors.cardBg ?? palette.toolPendingBg ?? "#17141d",
      palette,
    };

    const kit = createKit(pi);

    for (const entry of entries) {
      const entryData: EntryData = data.get(entry.id) ?? { states: {} };
      const revealEntry: Record<string, Record<CellKey, RevealStore>> = revealData.get(entry.id) ?? {};
      const blockEntry: Record<string, Record<CellKey, BlockCell>> = blockData.get(entry.id) ?? {};
      const fixtureEntry: Record<string, { lines: string[] }> = fixtures.get(entry.id) ?? {};

      for (const state of entry.states) {
        const byCell: Record<CellKey, string[]> = {};
        for (const width of widthsFor(entry, scope)) {
          for (const glyphMode of glyphsForScope(scope)) {
            const ctx = {
              pi,
              kit,
              theme: installed.theme,
              glyphs: glyphsFor(glyphMode),
              glyphMode,
              width,
              themeName,
            };
            const frameCount = state.frames ?? 1;
            const frameRows: string[][] = [];
            const revealPool: RevealCell[][] = [];
            const revealKeys = new Map<string, number>();
            const sharedReveal: number[] = [];
            const blockPool: Record<string, string> = {};
            const blockFrames: BlockCell["frames"] = [];
            for (let frame = 0; frame < frameCount; frame++) {
              const lines = state.render(ctx, frame);
              const rows = toRows(pi, lines);
              // Blocks outside a group: a click swaps the span for its full body.
              const opened = (state.toggles ? state.toggles(ctx, frame) : []).map((spec) => {
                const keys = spec.opens.map((bodyLines) => {
                  const body = toRows(pi, bodyLines);
                  const key = contentKey(body.join(""));
                  blockPool[key] ??= tagRows(body, "data-block", spec.key).join("");
                  return key;
                });
                return { row: spec.row, count: spec.count, id: spec.key, keys };
              });
              opened.forEach(({ row, count, id }) => {
                for (let at = row; at < row + count; at++) {
                  const line = rows[at];
                  if (line === undefined) continue;
                  rows[at] = line.replace('<div class="ansi-line"', `<div class="ansi-line" data-block="${id}"`);
                }
              });
              blockFrames.push(opened);
              frameRows.push(state.reveal ? markRows(rows, groupRowIndices(lines, ctx.glyphs.collapsed)) : rows);
              if (state.reveal) {
                const groups = state.reveal(ctx, frame).map((group, gi) => ({
                  header: tagRows(toRows(pi, group.header), "data-collapse", String(gi)).join(""),
                  members: group.members.map((member, mi) => {
                    const collapsed = toRows(pi, member.collapsed);
                    const tag = `${gi}:${mi}`;
                    // Nothing hidden: the row stays inert, no hint, no cursor.
                    const inert = collapsed.length >= toRows(pi, member.expanded).length;
                    const mark = (part: string[]) => (inert ? part.join("") : tagRows(part, "data-turn", tag).join(""));
                    return {
                      collapsed: mark(collapsed),
                      preview: mark(toRows(pi, member.preview)),
                      expanded: mark(toRows(pi, member.expanded)),
                    };
                  }),
                }));
                const key = contentKey(JSON.stringify(groups));
                let at = revealKeys.get(key);
                if (at === undefined) {
                  at = revealPool.length;
                  revealPool.push(groups);
                  revealKeys.set(key, at);
                }
                sharedReveal.push(at);
              }
              if (frame === 0 && entry.fixture !== false) {
                fixtureEntry[`${state.id}/${themeName}/${width}/${glyphMode}`] = { lines };
              }
            }
            const key = cellKey(width, themeName, glyphMode);
            const pool = frameCount > POOL_FRAME_THRESHOLD;
            byCell[key] = pool ? (pooled(frameRows) as unknown as string[]) : frameRows.map((rows) => rows.join(""));
            if (state.reveal) {
              revealEntry[state.id] = {
                ...revealEntry[state.id],
                [key]: { pool: revealPool, frames: sharedReveal },
              };
            }
            if (blockFrames.some((frame) => frame.length > 0)) {
              blockEntry[state.id] = { ...blockEntry[state.id], [key]: { pool: blockPool, frames: blockFrames } };
            }
          }
        }
        // Merge: each theme contributes its own cell keys to the same state.
        entryData.states[state.id] = { ...entryData.states[state.id], ...byCell };
      }

      data.set(entry.id, entryData);
      if (Object.keys(revealEntry).length > 0) revealData.set(entry.id, revealEntry);
      if (Object.keys(blockEntry).length > 0) blockData.set(entry.id, blockEntry);
      if (entry.fixture !== false) fixtures.set(entry.id, fixtureEntry);
    }
  }

  // Fail loudly if any cell is missing: a silent hole is how the gallery shipped empty once.
  for (const entry of entries) {
    for (const state of entry.states) {
      for (const themeName of themeNames) {
        for (const width of widthsFor(entry, scope)) {
          for (const glyphMode of glyphsForScope(scope)) {
            const cell = data.get(entry.id)?.states[state.id]?.[cellKey(width, themeName, glyphMode)] as
              | string[]
              | PooledCell
              | undefined;
            const expected = state.frames ?? 1;
            const actual = cell && Array.isArray(cell) ? cell.length : cell?.frames.length;
            if (!cell || actual !== expected) {
              throw new Error(`missing cell for ${entry.id}/${state.id} at ${cellKey(width, themeName, glyphMode)}`);
            }
          }
        }
      }
    }
  }

  const payload: PagePayload = {
    meta: {
      piVersion: pi.version,
      tuiVersion: pi.tuiVersion,
      source: pi.source,
      generatedAt: new Date().toISOString(),
      widths: [...WIDTHS],
      glyphs: [...GLYPH_MODES],
      spinners: Object.fromEntries(GLYPH_MODES.map((mode) => [mode, [...glyphsFor(mode).spinner]])),
      themes: [...THEME_NAMES],
      bodyLines: bodyLinesMap(),
    },
    themes,
    entries: entries.map((entry) => ({
      ...short(entry),
      data: data.get(entry.id)?.states ?? {},
      ...(revealData.get(entry.id) ? { reveal: revealData.get(entry.id) } : {}),
      ...(blockData.get(entry.id) ? { blocks: blockData.get(entry.id) } : {}),
    })),
  };

  return { payload, fixtures, pi };
}

const scopeOfMain: RenderScope = {};

async function main(): Promise<void> {
  const { payload, fixtures, pi } = await renderGallery(scopeOfMain);
  console.log(`pi ${pi.version} (${pi.source}) · tui ${pi.tuiVersion}`);

  const framesJson = JSON.stringify(Object.fromEntries(fixtures), null, 2);

  // --check: fail when committed fixtures no longer match what the components render.
  // This is the drift guard: the gallery cannot silently disagree with the code.
  if (process.argv.includes("--check")) {
    const committedPath = join(FIXTURES, "frames.json");
    const committed = existsSync(committedPath) ? readFileSync(committedPath, "utf8") : "";
    if (committed !== framesJson) {
      const next = Object.fromEntries(fixtures);
      const prev = committed ? (JSON.parse(committed) as Record<string, Record<string, unknown>>) : {};
      const drifted = [...new Set([...Object.keys(prev), ...Object.keys(next)])].filter(
        (id) => JSON.stringify(prev[id]) !== JSON.stringify(next[id]),
      );
      console.error(`stale fixtures: ${drifted.join(", ") || "whole file"}`);
      console.error("run `bun run ds` and commit the regenerated output");
      process.exitCode = 1;
      return;
    }
    console.log(`fixtures current: ${cellCount(ENTRIES, scopeOfMain)} cells across ${payload.entries.length} entries`);
    return;
  }

  mkdirSync(OUT, { recursive: true });
  mkdirSync(FIXTURES, { recursive: true });

  writeFileSync(join(OUT, "index.html"), renderPage(payload));
  writeFileSync(join(OUT, "spec.json"), JSON.stringify({ meta: payload.meta, entries: payload.entries }, null, 2));
  writeFileSync(join(FIXTURES, "frames.json"), framesJson);

  console.log(`rendered ${cellCount(ENTRIES, scopeOfMain)} cells across ${payload.entries.length} entries`);
  console.log(`wrote ${join(OUT, "index.html")}`);
}

if (import.meta.main) {
  // pi's imported modules leave handles open; exit explicitly so scripts finish.
  main().then(
    () => process.exit(process.exitCode ?? 0),
    (error) => {
      console.error(error);
      process.exit(1);
    },
  );
}

