// Say what a click does, on the row it applies to: open, preview, show all, fold.
// One inline wrapper: the tint covers the text, never the row's remaining width.
function lamp(row) {
  if (row.querySelector(':scope > .lamp')) return;
  row.innerHTML = '<span class="lamp">' + row.innerHTML + '</span>';
}

function annotateHints(term, entry, idx, stateId) {
  var prefix = entry.id + ':' + idx;
  var rows = [].slice.call(term.querySelectorAll('.ansi-line'));

  term.querySelectorAll('[data-collapse]').forEach(function (row) {
    row.setAttribute('data-hint', 'click · collapse');
    lamp(row);
  });
  // A member's hint lives on its final row.
  var turnGroups = {};
  rows.forEach(function (row) {
    var key = row.getAttribute('data-turn');
    if (!key) return;
    turnGroups[key] = turnGroups[key] || [];
    turnGroups[key].push(row);
  });
  Object.keys(turnGroups).forEach(function (key) {
    var st = revealOpenState[prefix + ':' + key] || 0;
    var hint = st === 0 ? 'click · expand' : 'click · collapse';
    turnGroups[key].forEach(function (row, order) {
      if (order === turnGroups[key].length - 1 && (st || /^\\+ \\d+ lines?$/.test(row.textContent.trim()))) {
        row.setAttribute('data-hint', hint);
        lamp(row);
      }
    });
  });

  // A single-row block carries its own hint.
  var cell = blocksFor(entry, stateId);
  (cell ? cell.frames[idx] || [] : []).forEach(function (spec) {
    var owned = [].slice.call(term.querySelectorAll('[data-block="' + spec.id + '"]'));
    var footer = owned[owned.length - 1];
    var st = blockOpenState[prefix + ':' + spec.id] || 0;
    if (!footer || (!st && !/^\\+ \\d+ lines?$/.test(footer.textContent.trim()))) return;
    footer.setAttribute('data-hint', st === 0 ? 'click · expand' : 'click · collapse');
    lamp(footer);

  });
}

/** Keep running glyphs moving even while a tool spends its real wait. */
function sparkle(html) {
  if (state.glyph === 'ascii') return html;
  var spinner = (DS.meta.spinners && DS.meta.spinners[state.glyph]) || [];
  if (spinner.length < 2) return html;
  var pattern = state.glyph === 'nerd'
    ? /[\\u{E000}-\\u{F8FF}\\u{F0000}-\\u{FFFFD}]/gu
    : /[\\u2800-\\u28FF]/g;
  var slot = 1000 / spinner.length;
  var stack = spinner.map(function (glyph, index) {
    return '<span style="animation-delay:-' + (index * slot) + 'ms">' + glyph + '</span>';
  }).join('');
  return html.replace(pattern, '<span class="spin n' + spinner.length + '" aria-hidden="true">' + stack + '</span>');
}

