];
code("event                 next   level  pending");
for (const [event, next] of events) {
  state = settleLevel(state.level, next, state.pending);
  code(`${event.padEnd(21)} ${String(next).padStart(4)}   ${String(state.level).padStart(5)}  ${String(state.pending ?? "—").padStart(7)}`);
}
note("The first change is held as pending; the second agreeing pass settles it.");

heading("8. Live folds: thinking and tools share one summary");
note("The live session has two render owners, so one plan in extensions/fold.ts keeps them in step.");
const component = (key) => ({ key });
const unit = (kind, key, distance, extra = {}) => ({
  kind,
  key,
  component: component(key),
  count: kind === "thinking" ? 1 : 1,
  cls: kind === "thinking" ? "thinking" : "shell",
  distance,
  invalidate: () => {},
  ...extra,
});
const units = [
  unit("thinking", "t0", 18, {
    tokens: { outputTokens: 120, inputTokens: 0 },
    startedAt: 1000,
    endedAt: 7000,
  }),
  unit("thinking", "t1", 17, {
    tokens: { outputTokens: 90, inputTokens: 0 },
    startedAt: 7050,
    endedAt: 9000,
  }),
  unit("thinking", "t2", 16, {
    tokens: { outputTokens: 70, inputTokens: 0 },
    startedAt: 9050,
    endedAt: 11000,
  }),
  ...Array.from({ length: 16 }, (_, index) =>
    unit("tool", `c${index}`, 15 - index, {
      tokens: { outputTokens: 8, inputTokens: 120 },
      startedAt: 11050 + index * 100,
      endedAt: 11100 + index * 100,
    }),
  ),
];
planFolds(units);
const anchor = thinkingPlan(units[0].component);
const group = anchor?.group;
code("unit      mode     level  group");
for (const name of ["t0", "t1", "c0", "c7", "c8", "c15"]) {
  const planFor = name.startsWith("t") ? thinkingPlan(units.find((u) => u.key === name).component) : toolPlan(name);
  code(
    `${name.padEnd(8)} ${String(planFor?.mode ?? "—").padEnd(8)} ${String(planFor?.level ?? "—").padStart(5)}  ${
      planFor?.group ? "shared" : "—"
    }`,
  );
}
if (group) {
  label("summary · collapsed");
  show(
    renderGroupRow(api, {
      segments: group.segments,
      tokens: group.tokens,
      durationMs: group.durationMs,
    }).render(WIDTH),
  );
  setGroupOpen(group, true);
  label("summary · open");
  show(
    renderGroupRow(api, {
      segments: group.segments,
      tokens: group.tokens,
      durationMs: group.durationMs,
      expanded: group.open,
    }).render(WIDTH),
  );
  note(`group timer ${formatDuration(group.durationMs)} · ${group.members.length} members · open=${group.open}`);
}

heading("9. Glyph sets");
note("A card must render in all three sets; ASCII is the accessibility floor.");
for (const [name, set] of [
  ["unicode", UNICODE_GLYPHS],
  ["ascii", ASCII_GLYPHS],
  ["nerd", NERD_GLYPHS],
]) {
  code(
    `${name.padEnd(8)} pending ${set.pending}  success ${set.success}  error ${set.error}  ` +
      `collapsed ${set.collapsed || "∅"}  expanded ${set.expanded || "∅"}  thinking ${set.thinking || "∅"}  ` +
      `spinner ${set.spinner.join(" ")}`,
  );
}

heading("10. One row per class");
note("The header carries the taxonomy: read/search/write/edit/shell/web/mcp/code/generic.");
const classRows = [
  { name: "read", args: { path: "src/core/session.ts" }, title: "src/core/session.ts", summary: "42 lines" },
  { name: "grep", args: { pattern: "registerToolRenderer" }, title: "registerToolRenderer", summary: "3 matches" },
  { name: "edit", args: { path: "render/detail.ts" }, title: "render/detail.ts", summary: "+8 −2" },
  { name: "bash", args: { command: "bun test" }, title: "bun test", summary: "28 passing" },
  { name: "mcp__memory__search", args: { query: "decay ladder" }, summary: "2 entries" },
  { name: "codemode", args: { task: "roll up calls" }, title: "roll up calls" },
  { name: "todo", args: { task: "unknown tool" }, title: "unknown tool" },
];
for (const row of classRows) {
  const input = {
    ...row,
    status: "success",
    level: 0,
    output: `output for ${row.name}`,
    durationMs: 90,
  };
  const meta = toolMeta(row.name);
  const counts = toolTokenCounts(input);
  label(`${row.name} → ${meta.cls} · "${meta.label}" · out ${counts.outputTokens} / in ${counts.inputTokens}`);
  show(renderToolLine(api, input).render(WIDTH));
}

note(`\nDone. Commands: bun run ds · bun run dev · bun run check · bun run e2e`);
note(`Gallery: http://localhost:4173 · goldens: design-system/fixtures/frames.json`);

